  function roundRect(ctx, x, y, w, h, r) {
    ctx.beginPath();
    if (ctx.roundRect) { ctx.roundRect(x, y, w, h, r); return; }
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y); ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r); ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h); ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r); ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }
  function haloText(ctx, txt, x, y, color, font, align) {
    ctx.font = font;
    ctx.textAlign = align || 'left';
    ctx.textBaseline = 'middle';
    ctx.lineJoin = 'round';
    ctx.lineWidth = Math.max(2, parseFloat(font) * 0.22);
    ctx.strokeStyle = '#fff';
    ctx.strokeText(txt, x, y);
    ctx.fillStyle = color;
    ctx.fillText(txt, x, y);
  }
  function curvedArrow(ctx, fx, fy, cx, cy, tx, ty, color, lw, head) {
    ctx.beginPath();
    ctx.moveTo(fx, fy);
    ctx.quadraticCurveTo(cx, cy, tx, ty);
    ctx.strokeStyle = color; ctx.lineWidth = lw; ctx.lineCap = 'round';
    ctx.stroke();
    var a = Math.atan2(ty - cy, tx - cx);
    ctx.beginPath();
    ctx.moveTo(tx, ty);
    ctx.lineTo(tx - head * Math.cos(a - 0.42), ty - head * Math.sin(a - 0.42));
    ctx.lineTo(tx - head * Math.cos(a + 0.42), ty - head * Math.sin(a + 0.42));
    ctx.closePath();
    ctx.fillStyle = color; ctx.fill();
  }

  // ---------- plugins ----------
  var fieldPlugin = {
    id: 'field',
    beforeDatasetsDraw: function (chart) {
      var a = chart.chartArea, ctx = chart.ctx;
      ctx.save();
      ctx.fillStyle = FIELD;
      ctx.fillRect(a.left, a.top, a.right - a.left, a.bottom - a.top);
      ctx.restore();
    }
  };

  var fontPlugin = {
    id: 'fonts',
    beforeLayout: function (chart) {
      var S = Math.min(chart.width, chart.height);
      var f = Math.max(8, Math.min(15, S / 30));
      var s = chart.options.scales;
      ['x', 'xTop', 'y'].forEach(function (k) {
        s[k].ticks.font = { size: f, family: 'sans-serif' };
        s[k].title.font = { size: f * 1.08, family: 'sans-serif' };
      });
    }
  };

  var overlayPlugin = {
    id: 'overlay',
    afterDatasetsDraw: function (chart) {
      var ctx = chart.ctx, a = chart.chartArea;
      var xs = chart.scales.x, ys = chart.scales.y;
      var w = a.right - a.left, h = a.bottom - a.top;
      var S = Math.min(w, h);
      var fs = Math.max(9, Math.min(17, S / 25));
      var lw = Math.max(1, S / 320);
      var PX = function (v) { return xs.getPixelForValue(v); };
      var PY = function (v) { return ys.getPixelForValue(v); };

      ctx.save();

      // --- annotations (leader arrows + labels) ---
      if (S > 190) {
        var font = fs + 'px sans-serif';
        ctx.font = font;
        var head = Math.max(4, S / 52);

        // more stable
        var tw = ctx.measureText('More stable isomer').width;
        var ax = Math.min(PX(10.25), a.right - tw - 4);
        var ay = PY(84);
        curvedArrow(ctx, ax - fs * 0.35, ay - fs * 0.15, PX(9.0), PY(90.5),
          PX(7.45), PY(93.6), '#111', lw, head);
        haloText(ctx, 'More stable isomer', ax, ay, '#111', font, 'left');

        // less stable
        var tw2 = ctx.measureText('Less stable isomer').width;
        var bx = Math.min(PX(10.0), a.right - tw2 - 4);
        var by = PY(14);
        curvedArrow(ctx, bx - fs * 0.35, by + fs * 0.1, PX(8.6), PY(8.4),
          PX(7.15), PY(6.6), '#111', lw, head);
        haloText(ctx, 'Less stable isomer', bx, by, '#111', font, 'left');
      }

      // --- shared start marker at (0, 50) ---
      var r = Math.max(2.4, S / 95);
      ctx.beginPath();
      ctx.arc(PX(0), PY(50), r, 0, Math.PI * 2);
      ctx.fillStyle = '#555'; ctx.fill();

      // --- interactive guide ---
      if (state.interacted) {
        var gx = PX(state.dE);
        var pm = pctMore(state.dE), pl = 100 - pm;
        ctx.save();
        ctx.setLineDash([5, 4]);
        ctx.strokeStyle = 'rgba(40,40,50,0.75)';
        ctx.lineWidth = Math.max(1, S / 380);
        ctx.beginPath(); ctx.moveTo(gx, a.top); ctx.lineTo(gx, a.bottom); ctx.stroke();
        ctx.restore();

        var dr = Math.max(3, S / 72);
        [[pm, BLUE], [pl, MAGENTA]].forEach(function (d) {
          ctx.beginPath();
          ctx.arc(gx, PY(d[0]), dr, 0, Math.PI * 2);
          ctx.fillStyle = d[1]; ctx.fill();
          ctx.lineWidth = Math.max(1, S / 340); ctx.strokeStyle = '#fff'; ctx.stroke();
        });

        // --- readout panel (drawn last, opaque) ---
        if (S > 170) {
          var f2 = Math.max(8.5, Math.min(14, S / 29));
          var pad = f2 * 0.75, lh = f2 * 1.42;
          var bw = Math.min(w * 0.42, Math.max(f2 * 13.5, 120));
          var barH = f2 * 0.78;
          var bh = pad * 2 + lh * 3.15 + barH + f2 * 0.6;
          var bx0 = a.left + w * 0.30;
          if (bx0 + bw > a.right - 4) bx0 = a.right - bw - 4;
          var by0 = a.top + h * 0.40;

          ctx.save();
          roundRect(ctx, bx0, by0, bw, bh, f2 * 0.45);
          ctx.fillStyle = 'rgba(255,255,255,0.95)';
          ctx.fill();
          ctx.lineWidth = 1; ctx.strokeStyle = '#9fb6c2'; ctx.stroke();

          var unit = state.kcal ? 'kcal/mol' : 'kJ/mol';
          var ev = state.kcal ? state.dE / KJ_PER_KCAL : state.dE;
          var tx0 = bx0 + pad, tx1 = bx0 + bw - pad;
          var yy = by0 + pad + lh * 0.45;

          ctx.textBaseline = 'middle';
          ctx.font = '600 ' + f2 + 'px sans-serif';
          ctx.fillStyle = '#111'; ctx.textAlign = 'left';
          ctx.fillText('ΔE = ' + ev.toFixed(2) + ' ' + unit, tx0, yy);

          ctx.font = f2 + 'px sans-serif';
          yy += lh;
          ctx.fillStyle = BLUE; ctx.textAlign = 'left';
          ctx.fillText('More stable', tx0, yy);
          ctx.textAlign = 'right';
          ctx.fillText(pm.toFixed(1) + ' %', tx1, yy);

          yy += lh;
          ctx.fillStyle = MAGENTA; ctx.textAlign = 'left';
          ctx.fillText('Less stable', tx0, yy);
          ctx.textAlign = 'right';
          ctx.fillText(pl.toFixed(1) + ' %', tx1, yy);

          // stacked bar
          var byBar = yy + lh * 0.55;
          var bwIn = tx1 - tx0;
          ctx.fillStyle = BLUE;
          ctx.fillRect(tx0, byBar, bwIn * pm / 100, barH);
          ctx.fillStyle = MAGENTA;
          ctx.fillRect(tx0 + bwIn * pm / 100, byBar, bwIn * pl / 100, barH);
          ctx.lineWidth = 1; ctx.strokeStyle = '#7d93a0';
          ctx.strokeRect(tx0, byBar, bwIn, barH);

          ctx.font = (f2 * 0.88) + 'px sans-serif';
          ctx.fillStyle = '#555'; ctx.textAlign = 'right';
          ctx.fillText('sum = 100 %', tx1, byBar + barH + f2 * 0.75);
          ctx.restore();
        }
      }
      ctx.restore();
    }
  };

  // ---------- chart ----------
  var chart = new Chart(canvas.getContext('2d'), {
    type: 'line',
    data: {
      datasets: [
        {
          label: 'More stable isomer', data: more, parsing: false,
          borderColor: BLUE, borderWidth: 2.2, pointRadius: 0, fill: false, tension: 0
        },
        {
          label: 'Less stable isomer', data: less, parsing: false,
          borderColor: MAGENTA, borderWidth: 2.2, pointRadius: 0, fill: false, tension: 0
        },
        {
          label: '_top', data: [{ x: 0, y: 0 }], parsing: false, xAxisID: 'xTop',
          borderColor: 'rgba(0,0,0,0)', backgroundColor: 'rgba(0,0,0,0)',
          pointRadius: 0, showLine: false
        }
      ]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      animation: false,
      interaction: { mode: null },
      plugins: { legend: { display: false }, tooltip: { enabled: false } },
      layout: { padding: { right: 6, top: 2, bottom: 2 } },
      scales: {
        x: {
          type: 'linear', position: 'bottom', min: 0, max: X_MAX,
          title: { display: true, text: 'Energy difference (kJ/mol)', color: '#111' },
          border: { color: '#000', width: 1.3 },
          grid: { color: GRID, lineWidth: 1, drawTicks: true, tickColor: '#000', tickLength: 5 },
          ticks: {
            stepSize: 1, color: '#111', autoSkip: false, maxRotation: 0,
            callback: function (v) { return (v === 5 || v === 10 || v === 15) ? v : ''; }
          }
        },
        xTop: {
          type: 'linear', position: 'top', min: 0, max: X_MAX / KJ_PER_KCAL,
          title: { display: true, text: 'Energy difference (kcal/mol)', color: '#111' },
          border: { color: '#000', width: 1.3 },
          grid: { drawOnChartArea: false, drawTicks: true, tickColor: '#000', tickLength: 5 },
          ticks: {
            stepSize: 1, color: '#111', autoSkip: false, maxRotation: 0,
            callback: function (v) { return (Math.abs(v - Math.round(v)) < 1e-6 && v <= 3) ? Math.round(v) : ''; }
          }
        },
        y: {
          type: 'linear', min: 0, max: 100,
          title: { display: true, text: 'Percent', color: '#111' },
          border: { color: '#000', width: 1.3 },
          grid: { color: GRID, lineWidth: 1, drawTicks: true, tickColor: '#000', tickLength: 5 },
          ticks: { stepSize: 20, color: '#111' }
        }
      }
    },
    plugins: [fieldPlugin, fontPlugin, overlayPlugin]
  });
  window.__markRendered();

  function redraw() { chart.update('none'); }

  // ---------- controls ----------
  window.update_energyGap = function (v) {
    state.dE = Math.max(0, Math.min(X_DATA_MAX, v));
    state.interacted = true;
    redraw();
  };
  window.toggle_unitReadout = function (on) {
    state.kcal = !!on;
    state.interacted = true;
    redraw();
  };
  window.showKeyInsight = function () {
    showPopup('Key insight',
      'Equilibrium population depends exponentially on energy: %more = 100/(1 + e^(−ΔE/RT)). ' +
      'An energy gap smaller than a single weak interaction — only a few kJ/mol — already turns a ' +
      '50:50 mixture into roughly 95:5. Beyond ~12 kJ/mol the curves flatten, so extra stability buys ' +
      'almost no additional population.');
  };

  // ---------- demo steps ----------
  var STEPS = [
    { t: 'No energy difference: a 50:50 mixture', n: 'With ΔE = 0 the two isomers are equally stable, so the curves meet at 50 percent. Neither form is favored at equilibrium.', dE: 0, kcal: false },
    { t: 'A small gap already tips the balance', n: 'Slide to about 2 kJ/mol — less than the energy of a weak interaction — and the mixture is already roughly 70:30. Tiny energy differences have outsized population consequences.', dE: 2, kcal: false },
    { t: 'The classic 95:5 split', n: 'Near 7.5 kJ/mol the more stable isomer accounts for about 95 percent of the mixture. This is the region where chemists start calling a conformer “strongly preferred”.', dE: 7.5, kcal: false },
    { t: 'Same slice, different units', n: 'Switch the readout to kcal/mol: the guide line does not move and the percentages are unchanged — 7.5 kJ/mol is simply 1.8 kcal/mol. The top and bottom axes describe one relationship.', dE: 7.5, kcal: true },
    { t: 'Diminishing returns at large ΔE', n: 'Push toward 12–14 kJ/mol and the less stable isomer drops below one percent; the curves flatten, so extra stability buys very little additional population.', dE: 13, kcal: false }
  ];

  var narrEl = document.getElementById('demoNarration');
  var titleEl = document.getElementById('stepTitle');
  var labEl = document.getElementById('stepLabel');
  var slider = document.getElementById('energyGapInput');
  var outEl = document.getElementById('energyGapVal');
  var chk = document.getElementById('unitReadoutInput');

  function showStepText(i) {
    titleEl.textContent = STEPS[i].t;
    narrEl.textContent = STEPS[i].n;
    labEl.textContent = (i + 1) + ' / ' + STEPS.length;
  }
  function applyStep(i) {
    state.step = i;
    var s = STEPS[i];
    slider.value = s.dE; outEl.value = s.dE;
    chk.checked = s.kcal;
    state.dE = s.dE; state.kcal = s.kcal; state.interacted = true;
    showStepText(i);
    redraw();
  }
  window.nextStep = function () { applyStep((state.step + 1) % STEPS.length); };
  window.prevStep = function () { applyStep((state.step - 1 + STEPS.length) % STEPS.length); };

  showStepText(0);   // step 0 = pristine default view, nothing applied yet

  // ---------- hover / click ----------
  function hit(e) {
    var rect = canvas.getBoundingClientRect();
    var px = e.clientX - rect.left, py = e.clientY - rect.top;
    var a = chart.chartArea;
    if (!a || px < a.left || px > a.right || py < a.top || py > a.bottom) return null;
    var xs = chart.scales.x, ys = chart.scales.y;
    var vx = Math.max(0, Math.min(X_DATA_MAX, xs.getValueForPixel(px)));
    var pm = pctMore(vx), pl = 100 - pm;
    var tol = Math.max(8, Math.min(a.right - a.left, a.bottom - a.top) / 34);
    var dm = Math.abs(py - ys.getPixelForValue(pm));
    var dl = Math.abs(py - ys.getPixelForValue(pl));
    if (dm <= tol && dm <= dl) return { which: 'more', x: vx, p: pm };
    if (dl <= tol) return { which: 'less', x: vx, p: pl };
    return null;
  }

  canvas.addEventListener('mousemove', function (e) {
    var h = hit(e);
    if (!h) { hideTooltip(); canvas.style.cursor = 'default'; return; }
    canvas.style.cursor = 'pointer';
    var name = h.which === 'more' ? 'More stable isomer' : 'Less stable isomer';
    showTooltip(name + ': ' + h.p.toFixed(1) + ' %  at ΔE = ' + h.x.toFixed(1) +
      ' kJ/mol (' + (h.x / KJ_PER_KCAL).toFixed(2) + ' kcal/mol)', e);
  });
  canvas.addEventListener('mouseleave', function () { hideTooltip(); });

  canvas.addEventListener('click', function (e) {
    var h = hit(e);
    if (h && h.which === 'more') {
      showPopup('More stable isomer',
        'This curve is 100/(1 + e^(−ΔE/RT)): the fraction of molecules sitting in the lower-energy form at 298 K. ' +
        'It climbs steeply at first — by ΔE ≈ 7.5 kJ/mol it is already about 95 % — then flattens as the mixture ' +
        'runs out of room to improve.');
    } else if (h && h.which === 'less') {
      showPopup('Less stable isomer',
        'This curve is the exact mirror of the blue one about the 50 % line, because the two populations must sum to 100 %. ' +
        'Its exponential decay means the higher-energy form is nearly gone (<1 %) once ΔE exceeds roughly 12 kJ/mol.');
    } else {
      showPopup('Boltzmann population split',
        'The equilibrium ratio of two isomers is K = e^(−ΔE/RT), with RT ≈ 2.48 kJ/mol at 298 K. ' +
        'Because the dependence is exponential, an energy gap of only a few kJ/mol already produces a strongly ' +
        'lopsided mixture. Drag the slider to slice the plot at any ΔE.');
    }
  });
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using Chart.js.

CONCEPT: At equilibrium, the population split between two isomers is set by their energy difference through the Boltzmann/Gibbs relation, so even a small energy gap (a few kJ/mol) produces a strongly lopsided mixture.
KEY INSIGHT (what students should walk away understanding): Equilibrium population depends exponentially on energy, so an energy gap smaller than a single weak bond — only a few kJ/mol — already makes the mixture roughly 95:5 rather than 50:50.
DEMO STEPS: 5 guided steps — implement the step player in #ui

