      var f = Math.max(8, Math.min(15, S / 30));
      var tl = Math.max(3, Math.min(6, S / 90));
      var s = chart.options.scales;
      ['x', 'xTop', 'y'].forEach(function (k) {
        s[k].ticks.font = { size: f, family: 'sans-serif' };
        s[k].title.font = { size: f * 1.08, family: 'sans-serif' };
        s[k].grid.tickLength = tl;
      });
    }
  };

  var overlayPlugin = {
    id: 'overlay',
    afterDatasetsDraw: function (chart) {
      var ctx = chart.ctx, a = chart.chartArea;
      var xs = chart.scales.x, ys = chart.scales.y;
      var w = a.right - a.left, h = a.bottom - a.top;
      var S = Math.min(w, h);
      var fs = Math.max(9, Math.min(17, S / 25));
      var lw = Math.max(1, S / 320);
      var PX = function (v) { return xs.getPixelForValue(v); };
      var PY = function (v) { return ys.getPixelForValue(v); };

      ctx.save();

      // --- annotations (leader arrows + labels) ---
      if (S > 190) {
        var font = fs + 'px sans-serif';
        ctx.font = font;
        var head = Math.max(4, S / 52);

        // more stable
        var tw = ctx.measureText('More stable isomer').width;
        var ax = Math.min(PX(10.25), a.right - tw - 4);
        var ay = PY(84);
        curvedArrow(ctx, ax - fs * 0.40, ay - fs * 0.15, PX(9.0), PY(90.5),
          PX(7.45), PY(93.6), '#111', lw, head);
        haloText(ctx, 'More stable isomer', ax, ay, '#111', font, 'left');

        // less stable
        var tw2 = ctx.measureText('Less stable isomer').width;
        var bx = Math.min(PX(10.0), a.right - tw2 - 4);
        var by = PY(14);
        curvedArrow(ctx, bx - fs * 0.40, by + fs * 0.1, PX(8.6), PY(8.4),
          PX(7.15), PY(6.6), '#111', lw, head);
        haloText(ctx, 'Less stable isomer', bx, by, '#111', font, 'left');
      }

      // --- interactive layer (hidden until the student acts) ---
      if (state.interacted) {
        var gx = PX(state.dE);
        var pm = pctMore(state.dE), pl = 100 - pm;

        ctx.save();
        ctx.setLineDash([5, 4]);
        ctx.strokeStyle = 'rgba(40,40,50,0.75)';
        ctx.lineWidth = Math.max(1, S / 380);
        ctx.beginPath(); ctx.moveTo(gx, a.top); ctx.lineTo(gx, a.bottom); ctx.stroke();
        ctx.restore();

        // shared meeting point marker (only while interacting)
        var r0 = Math.max(2.2, S / 110);
        ctx.beginPath();
        ctx.arc(PX(0), PY(50), r0, 0, Math.PI * 2);
        ctx.fillStyle = '#4a5a63'; ctx.fill();

        var dr = Math.max(3, S / 72);
        [[pm, BLUE], [pl, MAGENTA]].forEach(function (d) {
          ctx.beginPath();
          ctx.arc(gx, PY(d[0]), dr, 0, Math.PI * 2);
