          ctx.lineWidth = Math.max(1, S / 340); ctx.strokeStyle = '#fff'; ctx.stroke();
        });

        // --- readout panel, parked in the empty mid band on the right ---
        if (S > 170) {
          var f2 = Math.max(8.5, Math.min(14, S / 29));
          var pad = f2 * 0.75, lh = f2 * 1.42;
          var bw = Math.min(w * 0.42, Math.max(f2 * 13.5, 120));
          var barH = f2 * 0.78;
          var bh = pad * 2 + lh * 3.15 + barH + f2 * 0.6;

          var bx0 = a.right - bw - 6;
          if (gx > bx0 - 10) bx0 = Math.max(a.left + 6, gx - bw - 12);
          var by0 = PY(66);
          if (by0 + bh > PY(30)) by0 = Math.max(a.top + 4, PY(30) - bh);

          ctx.save();
          roundRect(ctx, bx0, by0, bw, bh, f2 * 0.45);
          ctx.fillStyle = 'rgba(255,255,255,0.96)';
          ctx.fill();
          ctx.lineWidth = 1; ctx.strokeStyle = '#9fb6c2'; ctx.stroke();

          var unit = state.kcal ? 'kcal/mol' : 'kJ/mol';
          var ev = state.kcal ? state.dE / KJ_PER_KCAL : state.dE;
          var tx0 = bx0 + pad, tx1 = bx0 + bw - pad;
          var yy = by0 + pad + lh * 0.45;

          ctx.textBaseline = 'middle';
          ctx.font = '600 ' + f2 + 'px sans-serif';
          ctx.fillStyle = '#111'; ctx.textAlign = 'left';
          ctx.fillText('ΔE = ' + ev.toFixed(2) + ' ' + unit, tx0, yy);

          ctx.font = f2 + 'px sans-serif';
          yy += lh;
          ctx.fillStyle = BLUE; ctx.textAlign = 'left';
          ctx.fillText('More stable', tx0, yy);
          ctx.textAlign = 'right';
          ctx.fillText(pm.toFixed(1) + ' %', tx1, yy);

          yy += lh;
          ctx.fillStyle = MAGENTA; ctx.textAlign = 'left';
          ctx.fillText('Less stable', tx0, yy);
          ctx.textAlign = 'right';
          ctx.fillText(pl.toFixed(1) + ' %', tx1, yy);

