          ctx.fillStyle = MAGENTA;
          ctx.fillRect(tx0 + bwIn * pm / 100, byBar, bwIn * pl / 100, barH);
          ctx.lineWidth = 1; ctx.strokeStyle = '#7d93a0';
          ctx.strokeRect(tx0, byBar, bwIn, barH);

          ctx.font = (f2 * 0.88) + 'px sans-serif';
          ctx.fillStyle = '#555'; ctx.textAlign = 'right';
          ctx.fillText('sum = 100 %', tx1, byBar + barH + f2 * 0.75);
