      datasets: [
        {
          label: 'More stable isomer', data: more, parsing: false,
          borderColor: BLUE, borderWidth: 2.2, pointRadius: 0, fill: false, tension: 0
        },
        {
          label: 'Less stable isomer', data: less, parsing: false,
          borderColor: MAGENTA, borderWidth: 2.2, pointRadius: 0, fill: false, tension: 0
        },
        {
          label: '_top', data: [{ x: 0, y: 0 }], parsing: false, xAxisID: 'xTop',
          borderColor: 'rgba(0,0,0,0)', backgroundColor: 'rgba(0,0,0,0)',
          pointRadius: 0, showLine: false
        }
      ]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      animation: false,
