      'An energy gap smaller than a single weak interaction — only a few kJ/mol — already turns a ' +
      '50:50 mixture into roughly 95:5. Beyond ~12 kJ/mol the curves flatten, so extra stability buys ' +
      'almost no additional population.');
  };

  // ---------- demo steps ----------
  var STEPS = [
    { t: 'No energy difference: a 50:50 mixture', n: 'With ΔE = 0 the two isomers are equally stable, so the curves meet at 50 percent. Neither form is favored at equilibrium.', dE: 0, kcal: false },
    { t: 'A small gap already tips the balance', n: 'Slide to about 2 kJ/mol — less than the energy of a weak interaction — and the mixture is already roughly 70:30. Tiny energy differences have outsized population consequences.', dE: 2, kcal: false },
    { t: 'The classic 95:5 split', n: 'Near 7.5 kJ/mol the more stable isomer accounts for about 95 percent of the mixture. This is the region where chemists start calling a conformer “strongly preferred”.', dE: 7.5, kcal: false },
    { t: 'Same slice, different units', n: 'Switch the readout to kcal/mol: the guide line does not move and the percentages are unchanged — 7.5 kJ/mol is simply 1.8 kcal/mol. The top and bottom axes describe one relationship.', dE: 7.5, kcal: true },
    { t: 'Diminishing returns at large ΔE', n: 'Push toward 12–14 kJ/mol and the less stable isomer drops below one percent; the curves flatten, so extra stability buys very little additional population.', dE: 13, kcal: false }
